1	import { PermissionBlur } from '@/shared/ui/PermissionBlur';
2	import { usePermissions } from '@/shared/hooks/usePermissions';
3	import EventosTimeline from './EventosTimeline';
4	
5	export default function Eventos() {
6	  const { canViewEventos } = usePermissions();
7	
8	  return (
9	    <PermissionBlur hasPermission={canViewEventos()} moduleName="Eventos">
10	      <div data-mia-page="eventos" data-mia-domain="logistica" className="contents">
11	        <EventosTimeline />
12	      </div>
13	    </PermissionBlur>
14	  );
15	}
16

1	import React, { useEffect, useState } from 'react';
2	import { useParams, useNavigate } from 'react-router-dom';
3	import { supabase } from '@/integrations/supabase/client';
4	import { useIsMobile } from '@/shared/hooks/use-mobile';
5	import { Button } from '@/shared/ui/button';
6	import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/shared/ui/tabs';
7	import { Card, CardContent } from '@/shared/ui/card';
8	import { Badge } from '@/shared/ui/badge';
9	import {
10	  ArrowLeft,
11	  Calendar,
12	  MapPin,
13	  DollarSign,
14	  TrendingUp,
15	  TrendingDown,
16	  Leaf,
17	  Package,
18	  ShoppingCart,
19	  CheckCircle,
20	} from 'lucide-react';
21	import { cn } from '@/shared/lib/utils';
22	import { toast } from '@/shared/hooks/use-toast';
23	import { wideInfo, wideError } from '@/shared/lib/telemetry/wide-events';
24	import { enrichWideEvent } from '@/shared/lib/telemetry/enrichWideEvent';
25	import { handleError } from '@/shared/lib/error-handler';
26	import { withTrace } from '@/shared/lib/telemetry/tracer';
27	import { recordOperation, recordOperationDuration, recordError } from '@/shared/lib/telemetry/metrics';
28	import { useTelemetryAttrs } from '@/shared/lib/telemetry/useTelemetryAttrs';
29	import {
30	  Select,
31	  SelectContent,
32	  SelectItem,
33	  SelectTrigger,
34	  SelectValue,
35	} from '@/shared/ui/select';
36	
37	// Sub-components
38	import { EventLogistics } from './EventLogistics';
39	import { EventFinance } from './EventFinance';
40	import { EventOverview } from './EventOverview';
41	import { useChangelog } from '@/features/eventos/model/useChangelog';
42	import { ChangelogViewer } from '@/features/eventos/ui/ChangelogViewer';
43	
44	interface Evento {
45	  id: string;
46	  nome: string;
47	  data_inicio: string;
48	  hora_inicio: string | null;
49	  endereco: string | null;
50	  status:
51	    | 'planejamento'
52	    | 'confirmado'
53	    | 'concluido'
54	    | 'cancelado'
55	    | 'aberto'
56	    | 'finalizado';
57	  faturamento: number | null;
58	  responsavel: string | null;
59	  telefone_responsavel: string | null;
60	  observacoes: string | null;
61	}
62	
63	interface MetricaEvento {
64	  totalReceita: number;
65	  totalDespesa: number;
66	  lucroLiquido: number;
67	  margemLucro: number;
68	  totalItens: number;
69	  itensVendidos: number;
70	  ticketMedio: number;
71	}
72	
73	export default function EventDashboard() {
74	  const { id } = useParams<{ id: string }>();
75	  const navigate = useNavigate();
76	  const isMobile = useIsMobile();
77	  const telemetryAttrs = useTelemetryAttrs();
78	  const [evento, setEvento] = useState<Evento | null>(null);
79	  const [loading, setLoading] = useState(true);
80	  const [activeTab, setActiveTab] = useState('overview');
81	  const [metricas, setMetricas] = useState<MetricaEvento | null>(null);
82	  const {
83	    logs,
84	    loading: loadingLogs,
85	    addLog,
86	    fetchLogs,
87	  } = useChangelog(id || '', 'EVENTO');
88	
89	  useEffect(() => {
90	    if (id) {
91	      fetchEvento(id);
92	      fetchMetricas(id);
93	    }
94	    // eslint-disable-next-line react-hooks/exhaustive-deps
95	  }, [id]);
96	
97	  const fetchEvento = async (eventId: string) => {
98	    setLoading(true);
99	    try {
100	      await withTrace('gerencia.evento_dashboard.carregar', async () => {
101	        const startTime = performance.now();
102	        const { data, error } = await supabase
103	          .from('eventos')
104	          .select('*')
105	          .eq('id', eventId)
106	          .single();
107	
108	        if (error) throw error;
109	        setEvento(data);
110	        const durationMs = Math.round(performance.now() - startTime);
111	        wideInfo('gerencia.evento_dashboard.carregado', 'Dashboard do evento carregado', enrichWideEvent('eventos', {
112	          'evento.id': eventId,
113	          'evento.nome': data?.nome ?? '',
114	          'evento.status': data?.status ?? '',
115	          duration_ms: durationMs,
116	        }));
117	        recordOperation('gerencia.evento_dashboard');
118	        recordOperationDuration('gerencia.evento_dashboard', durationMs);
119	      }, telemetryAttrs);
120	    } catch (error: any) {
121	      wideError('gerencia.evento_dashboard.erro', 'Erro ao carregar dashboard do evento', enrichWideEvent('eventos', {
122	        'error.message': error?.message ?? String(error),
123	        'evento.id': eventId,
124	        'evento.nome': evento?.nome ?? '',
125	        'evento.operacao': 'carregar_dashboard',
126	        'evento.status': evento?.status ?? '',
127	      }));
128	      recordError('gerencia_evento_dashboard', 'carregar');
129	      toast({
130	        title: 'Erro ao carregar evento',
131	        description: error.message,
132	        variant: 'destructive',
133	      });
134	      navigate('/eventos');
135	    } finally {
136	      setLoading(false);
137	    }
138	  };
139	
140	  const fetchMetricas = async (eventId: string) => {
141	    try {
142	      await withTrace('gerencia.evento_metricas.carregar', async () => {
143	        const startTime = performance.now();
144	        // Buscar transações financeiras
145	        const { data: transacoes } = await supabase
146	          .from('eventos_transacoes')
147	          .select('*')
148	          .eq('evento_id', eventId);
149	
150	        // Buscar produtos do evento
151	        const { data: produtos } = await supabase
152	          .from('eventos_produtos')
153	          .select('*')
154	          .eq('evento_id', eventId);
155	
156	        const totalReceita =
157	          transacoes
158	            ?.filter((t) => t.tipo === 'receita')
159	            .reduce((acc, t) => acc + t.valor, 0) || 0;
160	        const totalDespesa =
161	          transacoes
162	            ?.filter((t) => t.tipo === 'despesa')
163	            .reduce((acc, t) => acc + t.valor, 0) || 0;
164	        const lucroLiquido = totalReceita - totalDespesa;
165	        const margemLucro =
166	          totalReceita > 0 ? (lucroLiquido / totalReceita) * 100 : 0;
167	
168	        const totalItens = produtos?.length || 0;
169	        const itensVendidos =
170	          produtos?.filter((p) => p.quantidade_enviada - p.quantidade_retorno > 0)
171	            .length || 0;
172	        const ticketMedio = itensVendidos > 0 ? totalReceita / itensVendidos : 0;
173	
174	        setMetricas({
175	          totalReceita,
176	          totalDespesa,
177	          lucroLiquido,
178	          margemLucro,
179	          totalItens,
180	          itensVendidos,
181	          ticketMedio,
182	        });
183	
184	        const durationMs = Math.round(performance.now() - startTime);
185	        wideInfo('gerencia.evento_metricas.carregadas', 'Métricas do evento carregadas', enrichWideEvent('eventos', {
186	          'evento.id': eventId,
187	          'evento.total_receita': totalReceita,
188	          'evento.total_despesa': totalDespesa,
189	          'evento.lucro_liquido': lucroLiquido,
190	          'evento.total_itens': totalItens,
191	          'evento.itens_vendidos': itensVendidos,
192	          duration_ms: durationMs,
193	        }));
194	        recordOperation('gerencia.evento_metricas');
195	        recordOperationDuration('gerencia.evento_metricas', durationMs);
196	      }, telemetryAttrs);
197	    } catch (error) {
198	      handleError(error, { domain: 'eventos', operation: 'carregarMetricas', showToast: false });
199	    }
200	  };
201	
202	  const handleStatusChange = async (newStatus: string) => {
203	    if (!evento) return;
204	    try {
205	      await withTrace('gerencia.evento.salvar', async () => {
206	        const startTime = performance.now();
207	        const { error } = await supabase
208	          .from('eventos')
209	          .update({ status: newStatus })
210	          .eq('id', evento.id);
211	
212	        if (error) throw error;
213	        setEvento({ ...evento, status: newStatus as any });
214	        await addLog(
215	          'STATUS_CHANGE',
216	          `Status alterado de ${evento.status} para ${newStatus}`,
217	        );
218	        const durationMs = Math.round(performance.now() - startTime);
219	        wideInfo('gerencia.evento.status_alterado', 'Status do evento alterado', enrichWideEvent('eventos', {
220	          'evento.id': evento.id,
221	          'evento.nome': evento.nome,
222	          'evento.status_anterior': evento.status,
223	          'evento.status_novo': newStatus,
224	          duration_ms: durationMs,
225	        }));
226	        recordOperation('gerencia.evento');
227	        recordOperationDuration('gerencia.evento', durationMs);
228	      }, telemetryAttrs);
229	      toast({
230	        title: `Evento marcado como ${newStatus === 'finalizado' ? 'finalizado' : 'aberto'}`,
231	      });
232	    } catch (error: any) {
233	      wideError('gerencia.evento.erro', 'Erro ao alterar status do evento', enrichWideEvent('eventos', {
234	        'error.message': error?.message ?? String(error),
235	        'evento.id': evento.id,
236	        'evento.nome': evento?.nome ?? '',
237	        'evento.operacao': 'status_change',
238	        'evento.status': evento?.status ?? '',
239	      }));
240	      recordError('gerencia_evento', 'status_change');
241	      handleError(error, { domain: 'eventos', operation: 'alterarStatus', showToast: false });
242	      toast({
243	        title: 'Erro ao atualizar status',
244	        description: error.message,
245	        variant: 'destructive',
246	      });
247	    }
248	  };
249	
250	  const getStatusDisplay = (status: string) => {
251	    const normalizedStatus = ['aberto', 'planejamento', 'confirmado'].includes(
252	      status,
253	    )
254	      ? 'aberto'
255	      : 'finalizado';
256	    return {
257	      value: normalizedStatus,
258	      label: normalizedStatus === 'aberto' ? 'Aberto' : 'Finalizado',
259	      className:
260	        normalizedStatus === 'aberto'
261	          ? 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-300'
262	          : 'bg-green-100 text-green-800 border-green-200 dark:bg-green-900/30 dark:text-green-300',
263	    };
264	  };
265	
266	  if (loading)
267	    return (
268	      <div className="flex items-center justify-center h-screen bg-[#F5F5F0] dark:bg-[#0A0A0A]">
269	        Carregando...
270	      </div>
271	    );
272	  if (!evento)
273	    return (
274	      <div className="flex items-center justify-center h-screen bg-[#F5F5F0] dark:bg-[#0A0A0A]">
275	        Evento não encontrado
276	      </div>
277	    );
278	
279	  const statusInfo = getStatusDisplay(evento.status);
280	
281	  return (
282	    <div className="flex flex-col h-[100dvh] bg-white dark:bg-[#0A0A0A] overflow-hidden relative font-sans">
283	      {/* Store Awning Stripe Effect (Top Border) */}
284	      <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50" />
285	
286	      {/* Animated Plant Background Elements */}
287	      <div
288	        className="absolute top-[-5%] right-[-10%] w-[300px] h-[300px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse"
289	        style={{ animationDuration: '10s' }}
290	      >
291	        <Leaf className="w-full h-full text-[#57715B] rotate-12" />
292	      </div>
293	      <div
294	        className="absolute bottom-[-10%] left-[-15%] w-[400px] h-[400px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse delay-1000"
295	        style={{ animationDuration: '12s' }}
296	      >
297	        <Leaf className="w-full h-full text-[#57715B] -rotate-45" />
298	      </div>
299	
300	      {/* Soft Ambient Glows */}
301	      <div className="absolute top-[20%] left-[10%] w-[200px] h-[200px] bg-[#57715B]/5 rounded-full blur-[80px] pointer-events-none" />
302	      <div className="absolute bottom-[30%] right-[10%] w-[250px] h-[250px] bg-[#C5A065]/5 rounded-full blur-[80px] pointer-events-none" />
303	
304	      {/* Header */}
305	      <div className="relative z-20 px-6 pt-8 pb-4 flex items-center gap-4">
306	        <Button
307	          data-mia-action="voltar-eventos"
308	          variant="ghost"
309	          size="icon"
310	          onClick={() => navigate('/eventos')}
311	          className="rounded-full bg-white/50 dark:bg-white/10 hover:bg-white/80 dark:hover:bg-white/20 backdrop-blur-sm shadow-sm"
312	        >
313	          <ArrowLeft className="h-5 w-5 text-[#57715B] dark:text-[#E6DCCF]" />
314	        </Button>
315	        <div className="flex-1 min-w-0">
316	          <h1 className="text-xl font-bold text-[#2D362E] dark:text-white truncate leading-tight">
317	            {evento.nome}
318	          </h1>
319	          <div className="flex items-center text-xs text-muted-foreground gap-2 mt-0.5">
320	            <span className="flex items-center truncate">
321	              <Calendar className="h-3 w-3 mr-1 flex-shrink-0" />{' '}
322	              {new Date(evento.data_inicio).toLocaleDateString()}
323	            </span>
324	          </div>
325	        </div>
326	        <Select value={statusInfo.value} onValueChange={handleStatusChange}>
327	          <SelectTrigger
328	            data-mia-filter="status_evento"
329	            className={cn('w-[130px] h-8 text-xs', statusInfo.className)}
330	          >
331	            <SelectValue />
332	          </SelectTrigger>
333	          <SelectContent>
334	            <SelectItem value="aberto">Aberto</SelectItem>
335	            <SelectItem value="finalizado">Finalizado</SelectItem>
336	          </SelectContent>
337	        </Select>
338	      </div>
339	
340	      {/* Main Content */}
341	      <div className="flex-1 overflow-hidden flex flex-col relative z-10">
342	        <Tabs
343	          value={activeTab}
344	          onValueChange={setActiveTab}
345	          className="flex-1 flex flex-col"
346	        >
347	          {/* Apple-style Segmented Control */}
348	          <div className="px-6 pb-4">
349	            <TabsList className="w-full h-10 bg-[#E6DCCF]/40 dark:bg-white/5 p-1 rounded-xl grid grid-cols-5 backdrop-blur-sm">
350	              <TabsTrigger
351	                data-mia-action="tab-overview"
352	                value="overview"
353	                className="rounded-lg data-[state=active]:bg-white dark:data-[state=active]:bg-[#2A2A2A] data-[state=active]:shadow-sm text-[10px] sm:text-xs font-medium transition-all"
354	              >
355	                Visão Geral
356	              </TabsTrigger>
357	              <TabsTrigger
358	                data-mia-action="tab-logistics"
359	                value="logistics"
360	                className="rounded-lg data-[state=active]:bg-white dark:data-[state=active]:bg-[#2A2A2A] data-[state=active]:shadow-sm text-[10px] sm:text-xs font-medium transition-all"
361	              >
362	                Logística
363	              </TabsTrigger>
364	              <TabsTrigger
365	                data-mia-action="tab-finance"
366	                value="finance"
367	                className="rounded-lg data-[state=active]:bg-white dark:data-[state=active]:bg-[#2A2A2A] data-[state=active]:shadow-sm text-[10px] sm:text-xs font-medium transition-all"
368	              >
369	                Financeiro
370	              </TabsTrigger>
371	              <TabsTrigger
372	                data-mia-action="tab-changelog"
373	                value="changelog"
374	                className="rounded-lg data-[state=active]:bg-white dark:data-[state=active]:bg-[#2A2A2A] data-[state=active]:shadow-sm text-[10px] sm:text-xs font-medium transition-all"
375	              >
376	                Histórico
377	              </TabsTrigger>
378	              <TabsTrigger
379	                data-mia-action="tab-summary"
380	                value="summary"
381	                className="rounded-lg data-[state=active]:bg-white dark:data-[state=active]:bg-[#2A2A2A] data-[state=active]:shadow-sm text-[10px] sm:text-xs font-medium transition-all"
382	              >
383	                Resumo
384	              </TabsTrigger>
385	            </TabsList>
386	          </div>
387	
388	          <div className="flex-1 overflow-y-auto">
389	            <div className="px-6 pb-24">
390	              {/* VISÃO GERAL (Editable with Loss Tracking) */}
391	              <TabsContent
392	                value="overview"
393	                className="mt-0 animate-in fade-in slide-in-from-bottom-4 duration-500"
394	              >
395	                <EventOverview
396	                  eventoId={evento.id}
397	                  evento={evento}
398	                  onEventoUpdate={() => fetchEvento(evento.id)}
399	                />
400	              </TabsContent>
401	
402	              <TabsContent
403	                value="logistics"
404	                className="mt-0 animate-in fade-in slide-in-from-bottom-4 duration-500"
405	              >
406	                <EventLogistics eventoId={evento.id} />
407	              </TabsContent>
408	
409	              <TabsContent
410	                value="finance"
411	                className="mt-0 animate-in fade-in slide-in-from-bottom-4 duration-500"
412	              >
413	                <EventFinance eventoId={evento.id} />
414	              </TabsContent>
415	
416	              <TabsContent
417	                value="changelog"
418	                className="mt-0 animate-in fade-in slide-in-from-bottom-4 duration-500 h-full"
419	              >
420	                <Card className="rounded-[1.5rem] border-none bg-[#F5F5F0]/50 dark:bg-white/5 backdrop-blur-xl h-full shadow-inner">
421	                  <div className="p-6 h-full flex flex-col">
422	                    <h3 className="text-lg font-bold text-[#2D362E] dark:text-white mb-4 flex items-center gap-2">
423	                      <TrendingUp className="h-5 w-5 text-[#C5A065]" />
424	                      Histórico de Alterações
425	                    </h3>
426	                    <div className="flex-1 min-h-0">
427	                      <ChangelogViewer logs={logs} loading={loadingLogs} />
428	                    </div>
429	                  </div>
430	                </Card>
431	              </TabsContent>
432	
433	              {/* SUMMARY (Former Overview) */}
434	              <TabsContent
435	                value="summary"
436	                className="space-y-6 mt-0 animate-in fade-in slide-in-from-bottom-4 duration-500"
437	              >
438	                {/* Card de Resultado */}
439	                <div
440	                  className={cn(
441	                    'relative overflow-hidden rounded-[2rem] p-6',
442	                    'bg-gradient-to-br from-[#57715B] to-[#4A614D]',
443	                    'shadow-[0_8px_32px_-8px_rgba(87,113,91,0.3)]',
444	                  )}
445	                >
446	                  <div className="absolute top-0 right-0 p-4 opacity-10">
447	                    <DollarSign className="h-32 w-32 text-white" />
448	                  </div>
449	                  <div className="relative z-10">
450	                    <div className="text-xs font-medium text-white/80 uppercase tracking-wider mb-1">
451	                      Resultado Financeiro
452	                    </div>
453	                    <div className="text-3xl font-bold text-white mb-6">
454	                      R${' '}
455	                      {metricas?.lucroLiquido?.toLocaleString('pt-BR', {
456	                        minimumFractionDigits: 2,
457	                      }) || '0,00'}
458	                    </div>
459	                    <div className="grid grid-cols-2 gap-4">
460	                      <div className="bg-white/10 rounded-xl p-3 backdrop-blur-md border border-white/10">
461	                        <div className="text-white/70 text-[10px] uppercase mb-1">
462	                          Receita Total
463	                        </div>
464	                        <div className="font-semibold text-white flex items-center text-sm">
465	                          <TrendingUp className="h-3 w-3 mr-1" /> R${' '}
466	                          {metricas?.totalReceita?.toLocaleString('pt-BR') ||
467	                            '0'}
468	                        </div>
469	                      </div>
470	                      <div className="bg-white/10 rounded-xl p-3 backdrop-blur-md border border-white/10">
471	                        <div className="text-white/70 text-[10px] uppercase mb-1">
472	                          Despesas
473	                        </div>
474	                        <div className="font-semibold text-white flex items-center text-sm">
475	                          <TrendingDown className="h-3 w-3 mr-1" /> R${' '}
476	                          {metricas?.totalDespesa?.toLocaleString('pt-BR') ||
477	                            '0'}
478	                        </div>
479	                      </div>
480	                    </div>
481	                  </div>
482	                </div>
483	
484	                {/* Resumo de Métricas de Negócio e Logística */}
485	                <div className="space-y-4">
486	                  <h3 className="text-sm font-bold text-[#2D362E] dark:text-white px-1">
487	                    Indicadores de Performance
488	                  </h3>
489	                  <div className="grid grid-cols-2 gap-4">
490	                    <Card
491	                      className={cn(
492	                        'border-none rounded-[1.5rem]',
493	                        'bg-white dark:bg-[#1A1A1A] backdrop-blur-xl',
494	                        'border border-black/5 dark:border-white/10 shadow-md',
495	                      )}
496	                    >
497	                      <CardContent className="p-4">
498	                        <div className="flex items-center gap-3">
499	                          <div className="h-10 w-10 rounded-xl bg-[#57715B]/10 flex items-center justify-center">
500	                            <Package className="h-5 w-5 text-[#57715B]" />
501	                          </div>
502	                          <div>
503	                            <div className="text-2xl font-bold text-[#2D362E] dark:text-white">
504	                              {metricas?.itensVendidos || 0}
505	                            </div>
506	                            <div className="text-xs text-muted-foreground">
507	                              Itens Vendidos
508	                            </div>
509	                          </div>
510	                        </div>
511	                      </CardContent>
512	                    </Card>
513	
514	                    <Card
515	                      className={cn(
516	                        'border-none rounded-[1.5rem]',
517	                        'bg-white dark:bg-[#1A1A1A] backdrop-blur-xl',
518	                        'border border-black/5 dark:border-white/10 shadow-md',
519	                      )}
520	                    >
521	                      <CardContent className="p-4">
522	                        <div className="flex items-center gap-3">
523	                          <div className="h-10 w-10 rounded-xl bg-[#C5A065]/10 flex items-center justify-center">
524	                            <ShoppingCart className="h-5 w-5 text-[#C5A065]" />
525	                          </div>
526	                          <div>
527	                            <div className="text-2xl font-bold text-[#2D362E] dark:text-white">
