-- Constraint tying recorrente to configuration fields
do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'encomendas_recorrencia_config_consistency'
  ) then
    alter table public.encomendas
      add constraint encomendas_recorrencia_config_consistency
      check (
        (recorrente = false and recorrencia_tipo is null and recorrencia_dia_semana is null and recorrencia_dia_mes is null)
        or
        (recorrente = true and (
          (recorrencia_tipo = 'semanal' and recorrencia_dia_semana is not null and recorrencia_dia_mes is null)
          or
          (recorrencia_tipo = 'mensal' and recorrencia_dia_mes is not null and recorrencia_dia_semana is null)
        ))
      );
  end if;
end $$;

